class _FeedForward(nn.Module):
    """GEGLU feed-forward: Linear → GEGLU → Linear (official FFN, mult=2).

    Exposes the inner Sequential directly (keys ``0``/``2``) to match the
    official checkpoint naming ``layers.{i}.1.{0,2}``.
    """

    def __init__(self, dim: int, mult: int = 2):
        super().__init__()
        dim_inner = int(dim * mult * 2 / 3)  # 1024*2*2/3 = 1365
        self.ff = nn.Sequential(
            nn.Linear(dim, dim_inner * 2),
            _GEGLU(),
            nn.Linear(dim_inner, dim),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.ff(x)

    # checkpoint keys are layers.{i}.1.0 / layers.{i}.1.2 (Sequential indices)
    def __getattr__(self, name: str):
        if name == "ff":
            raise AttributeError(name)
        return super().__getattr__(name)

    @property
    def _modules(self):
        # alias the inner Sequential's children at the top level so
        # load_state_dict sees layers.{i}.1.0 / .2
        return self.ff._modules

